"""Green-Screen-Memes werden sauber freigestellt und landen mit echtem Alphakanal im Soundboard."""

import zipfile

import av
import numpy as np

from hebocon.memes import convert, cutout, key_color, main
from hebocon.server import MediaStore

GREEN = (20, 230, 30)  # BGR


def green_frame(w=64, h=48):
    img = np.zeros((h, w, 3), np.uint8)
    img[:] = GREEN
    img[16:32, 24:40] = (40, 40, 220)
    return img


def test_green_becomes_transparent_and_content_stays():
    img = green_frame()
    # Kantenpixel zu drei Vierteln Grün, wie nach einer Verkleinerung.
    img[16:32, 23] = (np.array(GREEN) * 3 + (40, 40, 220)) // 4
    rgb, alpha = cutout(img, key_color(img))
    assert alpha[0, 0] == 0 and alpha[24, 32] == 1
    # Die Kante wird eingezogen und läuft weich aus, statt hart abzubrechen.
    assert alpha[24, 23] == 0 and 0 < alpha[24, 26] < 1
    # Kein Grünschimmer an der Kante.
    assert rgb[24, 26, 1] <= max(rgb[24, 26, 0], rgb[24, 26, 2])


def write_clip(path, frames=12):
    with av.open(str(path), "w") as out:
        video = out.add_stream("libx264", rate=24)
        video.width, video.height, video.pix_fmt = 64, 48, "yuv420p"
        audio = out.add_stream("aac", rate=44100)
        for i in range(frames):
            out.mux(video.encode(av.VideoFrame.from_ndarray(green_frame(), format="bgr24")))
            samples = np.zeros((1, 1024), np.float32)
            frame = av.AudioFrame.from_ndarray(samples, format="fltp", layout="mono")
            frame.sample_rate, frame.pts = 44100, i * 1024
            out.mux(audio.encode(frame))
        out.mux(video.encode(None))
        out.mux(audio.encode(None))


def test_convert_writes_vp9_with_alpha_and_sound(tmp_path):
    src, dst = tmp_path / "Meme_001.mp4", tmp_path / "out.webm"
    write_clip(src)
    convert(src, dst)
    with av.open(str(dst)) as result:
        kinds = {s.type: s.codec_context.name for s in result.streams}
        assert kinds == {"video": "vp9", "audio": "opus"}
        decoder = av.CodecContext.create("libvpx-vp9", "r")
        frames = [f for p in result.demux(result.streams.video[0]) for f in decoder.decode(p)]
    assert frames and frames[0].format.name == "yuva420p"
    # Auf den sichtbaren Inhalt zugeschnitten statt des ganzen grünen Bilds.
    assert frames[0].width < 64 and frames[0].height < 48
    bgra = frames[0].to_ndarray(format="bgra")
    assert bgra[0, 0, 3] < 30 and bgra[bgra.shape[0] // 2, bgra.shape[1] // 2, 3] > 220


def test_import_adds_tiles_once(tmp_path):
    clip = tmp_path / "Meme_001.mp4"
    write_clip(clip)
    pack = tmp_path / "memes.zip"
    with zipfile.ZipFile(pack, "w") as z:
        z.write(clip, "Meme_001.mp4")
        z.writestr("liesmich.txt", "kein Video")
    media = tmp_path / "media"
    main([str(pack), "--media", str(media)])
    main([str(pack), "--media", str(media)])
    board = MediaStore(media).board
    assert [(b["name"], b["mime"], b["cutout"]) for b in board] == [("Meme 001", "video/webm", True)]
